from pathlib import Path

from app.services import users

#: Directory that data manifest paths are resolved against. ``None`` uses the
#: project's ``data/`` directory; tests may point this at another directory.
DATA_DIR: Path | None = None

_INVALID_SEGMENTS = {"", ".", ".."}


def _data_root() -> Path:
    """Return the base directory used to resolve data manifest paths."""
    if DATA_DIR is not None:
        return Path(DATA_DIR)
    cwd_data = Path.cwd() / "data"
    if cwd_data.is_dir():
        return cwd_data
    return Path(__file__).resolve().parents[2] / "data"


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_data_manifest(params: dict) -> tuple[int, dict]:
    raw = params.get("dir", "")
    if not isinstance(raw, str):
        return 400, {"error": "invalid path"}
    segments = raw.split("/") if raw else []
    if any(segment in _INVALID_SEGMENTS for segment in segments):
        return 400, {"error": "invalid path"}

    base = _data_root()
    try:
        base = base.resolve()
        target = base.joinpath(*segments).resolve()
        exists = target.is_dir()
    except (OSError, ValueError):
        return 404, {"error": "not found"}
    # Reject paths that escape the configured data directory (for example via
    # symlinks) before touching the file system.
    if not target.is_relative_to(base) or not exists:
        return 404, {"error": "not found"}

    entries = []
    for path in target.rglob("*"):
        if path.is_file():
            entries.append({"path": path.relative_to(target).as_posix(), "bytes": path.stat().st_size})
    entries.sort(key=lambda entry: entry["path"])
    return 200, {"entries": entries}
"}

